import sys
from collections import defaultdict

def main():
    N, X, D = map(int, sys.stdin.readline().split())
    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return

    D_abs = abs(D)
    residues = defaultdict(list)

    for m in range(N + 1):
        if m == 0:
            s_min = 0
            s_max = 0
        else:
            s_min = m * (m - 1) // 2
            s_max = m * (2 * N - m - 1) // 2
        low = X * m + D * s_min
        high = X * m + D * s_max
        a = min(low, high)
        b = max(low, high)
        residue = (X * m) % D_abs
        residues[residue].append((a, b))

    total = 0
    for r in residues:
        intervals = residues[r]
        intervals.sort()
        merged = []
        for interval in intervals:
            if not merged:
                merged.append(interval)
            else:
                last_start, last_end = merged[-1]
                curr_start, curr_end = interval
                if curr_start <= last_end + D_abs:
                    new_start = last_start
                    new_end = max(last_end, curr_end)
                    merged[-1] = (new_start, new_end)
                else:
                    merged.append(interval)
        for start, end in merged:
            count = ((end - start) // D_abs) + 1
            total += count
    print(total)

