        groups[congruence].append((interval_low, interval_high))

    total = 0
    abs_D = abs(D)
    for congruence, intervals in groups.items():
        intervals.sort()
        merged = []
        for low, high in intervals:
            if not merged:
                merged.append([low, high])
            else:
                last_low, last_high = merged[-1]
                if low <= last_high:
                    new_low = last_low
                    new_high = max(last_high, high)
                    merged[-1] = [new_low, new_high]
                else:
                    merged.append([low, high])
        for low, high in merged:
            count = (high - low) // abs_D + 1
            total += count

