def factorize(n):
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        current_divisors = []
        for d in divisors:
            current = d
            for _ in range(exp + 1):
                current_divisors.append(current)
                current *= p
        divisors = current_divisors
    return divisors

def main():
    N = int(sys.stdin.readline())
    # Compute case1: number of divisors of N-1 >=2
    if N == 1:
        case1 = 0
    else:
        m = N - 1
        factors = factorize(m)
