import sys
from collections import defaultdict

def main():
    H, W = map(int, sys.stdin.readline().split())
    A = []
    for _ in range(H):
        A.append(list(map(int, sys.stdin.readline().split())))
    B = []
    for _ in range(H):
        B.append(list(map(int, sys.stdin.readline().split())))

    C = [[A[i][j] + B[i][j] for j in range(W)] for i in range(H)]

    dp = [[defaultdict(set) for _ in range(W)] for _ in range(H)]

    # Initialize the starting cell
    dp[0][0][A[0][0]].add(C[0][0])
    dp[0][0][B[0][0]].add(C[0][0])

    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                continue
            current_dp = defaultdict(set)
            # Check top cell
            if i > 0:
                for s_prev in dp[i-1][j]:
                    for t_prev in dp[i-1][j][s_prev]:
                        new_s1 = s_prev + A[i][j]
                        new_t1 = t_prev + C[i][j]
                        current_dp[new_s1].add(new_t1)
                        new_s2 = s_prev + B[i][j]
                        new_t2 = t_prev + C[i][j]
                        current_dp[new_s2].add(new_t2)
            # Check left cell
            if j > 0:
                for s_prev in dp[i][j-1]:
                    for t_prev in dp[i][j-1][s_prev]:
                        new_s1 = s_prev + A[i][j]
                        new_t1 = t_prev + C[i][j]
                        current_dp[new_s1].add(new_t1)
                        new_s2 = s_prev + B[i][j]
                        new_t2 = t_prev + C[i][j]
                        current_dp[new_s2].add(new_t2)
            dp[i][j] = current_dp

    min_unbalanced = float('inf')
    for s in dp[H-1][W-1]:
        for t in dp[H-1][W-1][s]:
            current = abs(2 * s - t)
            if current < min_unbalanced:
                min_unbalanced = current
    print(min_unbalanced)

if __name__ == "__main__":
