                dp[i][j] = new_mask

    min_abs = float('inf')
    final_mask = dp[H-1][W-1]
    for bit in range(0, 2 * max_sum + 1):
        if final_mask & (1 << bit):
            s = bit - offset
            if abs(s) < min_abs:
                min_abs = abs(s)
