            return 0
        current_bit_of_K = (K >> bit) & 1
        max_val = 0

        if tight:
            if current_bit_of_K == 1:
                for b in [0, 1]:
                    new_tight = (b == current_bit_of_K)
                    contribution = (count_1[bit] if b == 0 else count_0[bit]) * (1 << bit)
                    res = contribution + dfs(bit - 1, new_tight)
                    max_val = max(max_val, res)
            else:
                b = 0
                new_tight = (b == current_bit_of_K)
                contribution = (count_1[bit] if b == 0 else count_0[bit]) * (1 << bit)
