import sys
from collections import deque

def main():
    n, u, v = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    def bfs(start):
        d = [-1] * (n + 1)
        q = deque()
        d[start] = 0
        q.append(start)
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if d[neighbor] == -1:
                    d[neighbor] = d[current] + 1
                    q.append(neighbor)
        return d

    d_u = bfs(u)
    d_v = bfs(v)

    max_dist = 0
    for i in range(1, n + 1):
        if d_u[i] < d_v[i]:
            if d_v[i] > max_dist:
                max_dist = d_v[i]

    print(max_dist - 1)

