        a = int(input[idx]); idx += 1
        b = int(input[idx]); idx += 1
        c = int(input[idx]); idx += 1
        packages.append((a, b, c))

    d_values = [a * M_b - b * M_a for a, b, c in packages]
    mid = N // 2
    left_packages = packages[:mid]
    right_packages = packages[mid:]

    def generate_subsets(packages, d_values):
        n = len(packages)
        subsets = {}
        for mask in range(1 << n):
            sum_d = 0
            cost = 0
            for i in range(n):
                if mask & (1 << i):
                    sum_d += d_values[i]
                    cost += packages[i][2]
            if sum_d in subsets:
                if cost < subsets[sum_d]:
                    subsets[sum_d] = cost
            else:
                subsets[sum_d] = cost
        return subsets

    left_subsets = generate_subsets(left_packages, d_values[:mid])
    right_subsets = generate_subsets(right_packages, d_values[mid:])

    min_cost = float('inf')
    for left_sum in left_subsets:
        target = -left_sum
        if target in right_subsets:
            total_cost = left_subsets[left_sum] + right_subsets[target]
            if left_sum == 0 and target == 0:
                if left_subsets[left_sum] == 0 and right_subsets[target] == 0:
                    continue
            if total_cost < min_cost:
                min_cost = total_cost

    if min_cost == float('inf'):
