    N = int(input[idx]); idx +=1
    Ma = int(input[idx]); idx +=1
    Mb = int(input[idx]); idx +=1
    packages = []
    for _ in range(N):
        a = int(input[idx]); idx +=1
        b = int(input[idx]); idx +=1
        c = int(input[idx]); idx +=1
        packages.append((a, b, c))

    max_a = N * 10
    max_b = N * 10
    INF = float('inf')
    dp = [[INF] * (max_b + 1) for _ in range(max_a + 1)]
    dp[0][0] = 0

    for a, b, c in packages:
        for i in range(max_a, -1, -1):
            for j in range(max_b, -1, -1):
                if dp[i][j] != INF:
                    new_i = i + a
                    new_j = j + b
                    if new_i <= max_a and new_j <= max_b:
                        if dp[new_i][new_j] > dp[i][j] + c:
                            dp[new_i][new_j] = dp[i][j] + c

    min_cost = INF
    for i in range(max_a + 1):
        for j in range(max_b + 1):
            if i * Mb == j * Ma:
                if i == 0 and j == 0:
                    continue
                if dp[i][j] < min_cost:
                    min_cost = dp[i][j]

    print(-1 if min_cost == INF else min_cost)

if __name__ == "__main__":
    main()
