import sys
import itertools

def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, val in enumerate(is_prime) if val]
    return primes

def legendre(n, p):
    count = 0
    while n > 0:
        n = n // p
        count += n
    return count

def main():
    N = int(sys.stdin.readline())
    primes = sieve(N)
    exponents = [legendre(N, p) for p in primes]
    factors = [1, 3, 5, 15, 25, 75]
    result = []

    def generate_factor_lists(target, current_list):
        if target == 1:
            result.append(current_list.copy())
            return
        for f in factors:
            if target % f == 0:
                current_list.append(f)
                generate_factor_lists(target // f, current_list)
                current_list.pop()

    generate_factor_lists(75, [])

    total = 0
    for factor_list in result:
        perms = set(itertools.permutations(factor_list))
        for perm in perms:
            available_indices = list(range(len(primes)))
            ways = 1
            for factor in perm:
                required = factor - 1
                count = 0
                for i in available_indices:
                    if exponents[i] >= required:
                        count += 1
                if count == 0:
                    break
                ways *= count
                for i in range(len(available_indices)):
                    if exponents[available_indices[i]] >= required:
                        available_indices.pop(i)
                        break
            total += ways
    print(total)

if __name__ == "__main__":
    main()
